#include <stdio.h>

int is_leap(int year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

int main(void) {
    int year;
    scanf("%d", &year);
    printf("%d\n", is_leap(year));
    return 0;
}
